// Trích xuất thông tin khách và câu hỏi
const msg = $json.body || $json;
const customerName = msg.senderName || msg.from?.first_name || 'Quý khách';
const customerPhone = msg.phone || '';
const text = (msg.text || msg.message || '').trim();
const channel = msg.channel || 'Zalo OA / Web Chat';

// Nhận diện ý định khách hàng (Intent Detection)
let intent = 'HOI_THONG_TIN';
const lower = text.toLowerCase();

if (lower.includes('mua') || lower.includes('đăng ký') || lower.includes('báo giá') || lower.includes('đặt bàn') || lower.includes('liên hệ')) {
  intent = 'TIEM_NANG_MUA_HANG';
} else if (lower.includes('lỗi') || lower.includes('hỏng') || lower.includes('hỗ trợ') || lower.includes('không vào được')) {
  intent = 'HO_TRO_KY_THUAT';
}

// Soạn câu trả lời tự động chuẩn mực Phú Yên
let reply = '';
if (intent === 'TIEM_NANG_MUA_HANG') {
  reply = `Dạ chào ${customerName}, Đất Phú rất hân hạnh được hỗ trợ Quý khách! Về dịch vụ/đơn hàng anh/chị đang quan tâm, em đã chuyển thông tin tới chuyên viên phụ trách. Chuyên viên Đất Phú sẽ liên hệ trao đổi cụ thể ngay sau ít phút ạ!`;
} else if (intent === 'HO_TRO_KY_THUAT') {
  reply = `Dạ chào ${customerName}, bộ phận kỹ thuật Đất Phú đã ghi nhận sự cố của Quý khách và đang kiểm tra ngay trên hệ thống. Nếu gấp anh/chị có thể gọi hotline trực ban để được xử lý ngay lập tức ạ!`;
} else {
  reply = `Dạ chào ${customerName}, cảm ơn Quý khách đã liên hệ Tổ Hợp Dịch Vụ Đất Phú (Tuy Hòa, Phú Yên). Em là Trợ lý số Đất Phú AI, anh/chị cần thông tin về món ngon quán ăn hay dịch vụ chữ ký số/hóa đơn điện tử thì cứ nhắn em nhé!`;
}

return [{
  json: {
    customerName: customerName,
    customerPhone: customerPhone,
    question: text,
    channel: channel,
    intent: intent,
    reply: reply,
    time: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })
  }
}];

